import re
from lxml import etree

def extract(data):
    # Parse the XML data
    root = etree.fromstring(data)

    # Extract the title
    title = root.xpath('//h1[@class="main-title"]/text()')[0]

    # Extract the blocks
    blocks = []
    for block in root.xpath('//div[@class="article"]'):
        kind = block.xpath('.//span[@class="keyword"]/text()')[0]
        text = block.xpath('.//p/text()')[0]
        if kind == 'paragraph':
            blocks.append({'kind': kind, 'text': text})
        elif kind == 'subheading':
            blocks.append({'kind': kind, 'text': text})
        elif kind == 'caption':
            blocks.append({'kind': kind, 'text': text})
        elif kind == 'table':
            rows = []
            for row in block.xpath('.//tr'):
                cells = []
                for cell in row.xpath('.//td'):
                    cells.append(cell.text)
                rows.append(cells)
            blocks.append({'kind': kind, 'text': '\n'.join(rows)})

    # Extract the metadata
    metadata = {}
    for meta in root.xpath('//meta[@name="robots"]'):
        kind = meta.get('content')
        text = meta.get('content', '')
        if kind == 'noindex':
            metadata['noindex'] = True
        elif kind == 'nofollow':
            metadata['nofollow'] = True
        elif kind == 'nofollow':
            metadata['nofollow'] = True
        elif kind == 'noarchive':
            metadata['noarchive'] = True
        elif kind == 'noimage':
            metadata['noimage'] = True
        elif kind == 'nogzip':
            metadata['nogzip'] = True
        elif kind == 'noredirect':
            metadata['noredirect'] = True
        elif kind == 'notranslate':
            metadata['notranslate'] = True
        elif kind == 'nofollow':
            metadata['nofollow'] = True

    # Extract the excluded
    excluded = {}
    for excluded in root.xpath('//div[@class="article"]//span[@class="exclude"]'):
        kind = excluded.get('class')
        text = excluded.get('data-sudaclick')
        if kind == 'content_marketkeywords_p':
            excluded['kind'] = kind
            excluded['text'] = text

    # Extract the warnings
    warnings = []
    for warning in root.xpath('//div[@class="article"]//span[@class="warning"]'):
        kind = warning.get('class')
        text = warning.get('data-sudaclick')
        if kind == 'content_marketkeywords_p':
            warnings.append(kind)

    return {'title': title, 'blocks': blocks, 'metadata': metadata, 'excluded': excluded, 'warnings': warnings}
