import re
from lxml import etree

def extract(data):
    doc = etree.HTML(data)
    root = doc.xpath('//html//body')
    if not root:
        raise ValueError("No HTML found in the input data")

    title = root.xpath('.//h1/text()')[0] if root.xpath('.//h1') else None
    blocks = []
    metadata = []
    excluded = []
    warnings = []

    for node in root.xpath('.//p'):
        kind = node.xpath('text()[1]/text()').strip()
        text = node.xpath('text()[2]/text()').strip()
        xpath = node.xpath('xpath()')
        if kind == 'paragraph':
            blocks.append({'kind': kind, 'text': text})
        elif kind == 'subheading':
            blocks.append({'kind': kind, 'text': text, 'xpath': xpath})
        elif kind == 'caption':
            blocks.append({'kind': kind, 'text': text, 'xpath': xpath})
        elif kind == 'table':
            rows = []
            for row in node.xpath('.//tr'):
                cells = []
                for cell in row.xpath('.//td'):
                    cells.append(cell.text)
                rows.append(cells)
            metadata.append({'kind': kind, 'text': text, 'xpath': xpath, 'rows': rows})
        elif kind == 'image':
            warnings.append(f"Warning: Image pixel extraction not implemented.")
        elif kind == 'script':
            warnings.append(f"Warning: Script extraction not implemented.")
        elif kind == 'noscript':
            warnings.append(f"Warning: NoScript extraction not implemented.")
        else:
            warnings.append(f"Warning: Unrecognized element type: {kind}")

    return {'title': title, 'blocks': blocks, 'metadata': metadata, 'excluded': excluded, 'warnings': warnings}
